// KAN-165: the fake server answers exactly what the real endpoints answered.
//
// ttstats/pingpong/tests/fixtures/live_contract.json is generated by running
// live_contract.SCRIPTS through the real live_sync and /live/state/
// (test_live_contract.py fails when it is stale). Here the same scripts run
// through FakeServer, normalised the same way (live_contract.py's
// `normalise`; keep the two in step), and every answer must match.
//
// Run: npm run test:js
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { describe, test } from 'node:test';
import { FakeServer } from './live_fakes.mjs';

const contract = JSON.parse(readFileSync(
  new URL('../../ttstats/pingpong/tests/fixtures/live_contract.json', import.meta.url), 'utf8'));

const KEYS = ['error', 'applied_seq', 'rev', 'is_live', 'is_match_complete',
  'current_server', 'should_prompt_side_switch', 'rejected'];

function normaliseState(state, roles) {
  const out = {};
  for (const [k, v] of Object.entries(state || {})) {
    if (k !== 'last_point_at' && k !== 'events') out[k] = v;
  }
  if (state && 'events' in state) {
    out.events = state.events.map((e) => {
      const event = {};
      for (const [k, v] of Object.entries(e)) if (k !== 't') event[k] = v;
      if ('by' in event) event.by = roles[event.by] || '?';
      return event;
    });
  }
  return out;
}

function normalise(status, body, roles) {
  if (body === null || body === undefined) return { status };
  const out = { status };
  for (const key of KEYS) if (key in body) out[key] = body[key];
  if ('me' in body) {
    const me = body.me;
    if (me === null) out.me = null;
    else {
      out.me = {};
      for (const [k, v] of Object.entries(me)) if (k !== 'player_id') out.me[k] = v;
      out.me.player = roles[me.player_id] || '?';
    }
  }
  if ('state' in body) out.state = normaliseState(body.state, roles);
  if ('redirect_url' in body) {
    const url = body.redirect_url;
    out.redirect_url = url === null ? null : (/\/confirm\/$/.test(url) ? 'confirm' : 'detail');
  }
  if ('last_point' in body) {
    const lp = body.last_point;
    out.last_point = lp === null ? null : { sequence: lp.sequence, side: lp.side, by: roles[lp.by] || '?' };
  }
  if ('scorers' in body) {
    out.scorers = body.scorers.map((s) => ({
      role: s.role, side: s.side, applied_seq: s.applied_seq, revoked: s.revoked,
      can_score_both: s.can_score_both,
    }));
  }
  // JSON round trip: undefined members vanish, as they would on the wire.
  return JSON.parse(JSON.stringify(out));
}

async function run(script) {
  const server = script.shared ? FakeServer.shared(script.best_of) : new FakeServer(script.best_of);
  const roles = Object.fromEntries(server.scorers.map((s) => [s.player_id, s.role]));
  const answers = [];
  for (const step of script.steps) {
    let resp;
    if (step.call === 'sync') {
      const ops = step.ops.map((op) => ('expects_by' in op
        ? { ...op, expects_by: server.scorer(op.expects_by).player_id } : op));
      resp = server.sync(ops, { as: step.as });
    } else if (step.call === 'remove') {
      resp = server.remove(step.target, { as: step.as });
    } else if (step.since === null || step.since === undefined) {
      resp = server.stateAnswer({ as: step.as });
    } else {
      const since = step.since === 'rev' ? server.rev : step.since;
      resp = await server.poll({ as: step.as, since, wait: Boolean(step.wait) });
    }
    answers.push(normalise(resp.status, resp.body, roles));
  }
  return answers;
}

describe('FakeServer matches the real endpoints (live_contract.json)', () => {
  for (const { script, answers } of contract.scripts) {
    test(script.name, async () => {
      const got = await run(script);
      assert.equal(got.length, answers.length);
      got.forEach((answer, i) => {
        assert.deepEqual(answer, answers[i], `step ${i}: ${JSON.stringify(script.steps[i])}`);
      });
    });
  }

  test('the fixture exercises every script', () => {
    assert.deepEqual(contract.scripts.map((s) => s.script.name),
      ['shared_two_streams', 'shared_takeover', 'solo_host']);
  });
});
